//! Generate the checked-in TypeScript Ontology SDK.
//!
//! `poie-sdkgen --check` fails when the generated file differs; CI uses it to
//! prevent catalog/SDK drift. The input is the same Base-01 model the host uses.

use std::path::Path;
use std::process::ExitCode;

fn main() -> ExitCode {
    let check = std::env::args().skip(1).any(|arg| arg == "--check");
    match run(check) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("poie-sdkgen: {error}");
            ExitCode::from(2)
        }
    }
}

fn run(check: bool) -> Result<(), String> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let model = poie_ontology::model::Model::load(&root.join("scenarios/base-01/model.toml"))
        .map_err(|error| format!("load Base-01: {error}"))?;
    let catalog = poie_objects::build_catalog(&model).map_err(|error| format!("build catalog: {error}"))?;
    let generated = render(&catalog);
    let target = root.join("apps/desktop/src/sdk/ontology.ts");
    if check {
        let current = std::fs::read_to_string(&target).map_err(|error| format!("read SDK: {error}"))?;
        if current != generated {
            return Err(format!("generated SDK differs from {}", target.display()));
        }
        return Ok(());
    }
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent).map_err(|error| format!("create SDK dir: {error}"))?;
    }
    std::fs::write(&target, generated).map_err(|error| format!("write SDK: {error}"))?;
    println!("wrote {}", target.display());
    Ok(())
}

fn render(catalog: &poie_objects::OntologyCatalog) -> String {
    let mut out = String::new();
    out.push_str("// Generated by poie-sdkgen. Do not edit by hand.\n");
    out.push_str(&format!("// model digest: {}\n", catalog.model_digest));
    out.push_str(&format!("// catalog digest: {}\n", catalog.catalog_digest));
    out.push_str("/* eslint-disable */\n\n");
    out.push_str("export type ObjectTypeId = ");
    let ids: Vec<String> = catalog.object_types.iter().map(|object| format!("\"{}\"", object.id)).collect();
    out.push_str(&ids.join(" | "));
    out.push_str(";\n\n");
    out.push_str("export type FunctionId = ");
    let functions: Vec<String> = catalog.functions.iter().map(|function| format!("\"{}\"", function.id)).collect();
    out.push_str(&functions.join(" | "));
    out.push_str(";\n\n");
    out.push_str("export interface PropertyValue {\n  value: unknown;\n  source: \"model\" | \"declared\" | \"observed\" | \"evidence\";\n  asOf: string | null;\n  verification: string;\n}\n\n");
    out.push_str("export interface ObjectInstance {\n  id: string;\n  typeId: ObjectTypeId;\n  version: string;\n  properties: Record<string, PropertyValue>;\n}\n\n");
    out.push_str("export interface LinkInstance { typeId: string; from: string; to: string }\n");
    out.push_str("export interface EvidenceRef { kind: string; id: string; fingerprint: string | null; sha256: string | null; asOf: string | null; source: string }\n\n");
    out.push_str("export interface ObjectPage { schema: string; modelDigest: string; catalogDigest: string; objects: ObjectInstance[]; nextCursor: string | null }\n");
    out.push_str("export interface ObjectDetail { schema: string; modelDigest: string; catalogDigest: string; object: ObjectInstance; links: LinkInstance[]; evidence: EvidenceRef[] }\n\n");
    out.push_str("export interface ActionType { id: string; targetTypes: string[]; inputs: FlowView[]; outputs: FlowView[]; occupies: string[]; restores: string[]; requiresCapabilities: string[]; durationS: number | null; requiredVerification: string }\n");
    out.push_str("export interface FlowView { resource: string; quantity: string; unit: string }\n");
    out.push_str("export interface FunctionType { id: FunctionId; description: string; inputSchema: unknown; outputSchema: unknown; effect: string }\n\n");
    out.push_str("export interface OntologyCatalog { schema: string; modelDigest: string; catalogDigest: string; objectTypes: ObjectType[]; linkTypes: LinkType[]; actionTypes: ActionType[]; functions: FunctionType[] }\n");
    out.push_str("export interface ObjectType { id: ObjectTypeId; label: string; properties: PropertyDef[] }\n");
    out.push_str("export interface LinkType { id: string; from: string; to: string; cardinality: string }\n");
    out.push_str("export interface PropertyDef { id: string; label: string; kind: string; unit: string | null; required: boolean; readOnly: boolean; source: string }\n\n");
    out.push_str("export const ACTION_TYPE_IDS = [");
    let actions: Vec<String> = catalog.action_types.iter().map(|action| format!("\"{}\"", action.id)).collect();
    out.push_str(&actions.join(", "));
    out.push_str("] as const;\n");
    out.push_str("export const CATALOG_DIGEST = \"");
    out.push_str(&catalog.catalog_digest);
    out.push_str("\" as const;\n");
    out
}

#[cfg(test)]
mod tests {
    #[test]
    fn generated_sdk_is_checked_in() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let model = poie_ontology::model::Model::load(&root.join("scenarios/base-01/model.toml")).unwrap();
        let catalog = poie_objects::build_catalog(&model).unwrap();
        let generated = super::render(&catalog);
        let current = std::fs::read_to_string(root.join("apps/desktop/src/sdk/ontology.ts")).unwrap();
        assert_eq!(generated, current);
    }
}
